# -*- coding: utf-8 -*-
"""C0738 milit-: independent Chinese learner explanations, no images."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def A(h,w,m):return h+[[w,m]]
MIL=[['拉丁 miles，属格 militis','士兵；更早来源尚无定论']]
ARY=MIL+[['拉丁 militaris → 法语 militaire／直接借入英语','士兵的、军事的'],['中古英语 militari → military','军事的；后来 the military 指军队整体']]
ANT=MIL+[['拉丁 militare → militans / militantem','当兵、作战 → 正在作战的'],['法语 militant／拉丁语 → 英语 militant','战斗的；发展为为某种主张积极争斗、态度强硬的']]
ITIA=MIL+[['拉丁 militia','服兵役、军旅活动'],['英语 militia','早期指军事训练或制度；后来指民兵组织等非普通常备军力量']]
IZE=A(ARY,'英语 military 词基 + -ize → militarize','使具有军事组织、装备或用途')
DE=A(IZE,'英语 de- 撤除 + militarize → demilitarize','撤除军事部署、组织或功能，使非军事化')
W=[
E('military','英 /ˈmɪlɪtəri/；美 /ˈmɪləteri/','军事的；军用的；军队','想象一套为国防和作战组织起来的人员、设施与活动：制服、训练、基地等都可以用 military 描述。','来自拉丁 militaris“士兵的”，经法语 militaire 或直接借入英语；milit- 来自 miles 的词干，-ary 对应形容词结尾。不是英语 mile“英里”加后缀。',ARY,'a military hospital 是军队体系中的医院，不表示正在打仗。the military 作名词泛指军队整体，可能包括海陆空等军种，不只限于陆军。','military service；a military base；join the military；military and civilian personnel。','army 通常指陆军；the military 范围更广。military 本身只是领域描述，militaristic 则常含崇尚军力的评价。',('She grew up near a military base.','她在一座军事基地附近长大。'),('He joined the military after finishing school.','他完成学业后参了军。'),sources=[S('military'),M('military')]),
E('militia','/məˈlɪʃə/','民兵组织；民兵武装','把平时不是普通职业军人的人组织成武装力量，在特定需要下承担防卫等任务，是这个词的典型历史画面。','直接来自拉丁 militia“服兵役、军事活动”，而 militia 本身来自 miles“士兵”。它是独立借入的名词，不是把英语 military 的末尾改一改。',ITIA,'在不同历史或政治语境中，militia 可以是受政府组织的民兵，也可以是非国家武装；不能单凭这个词就判断它是否合法或属于哪一方。某些地区的历史制度名称也曾用它对应警察。','a local militia；a militia group；members of the militia；plural militias。','military 泛指军队体系；militia 常突出有别于普通职业常备军的组织方式。具体性质要看上下文。',('The history book describes how the town organized a militia.','历史书介绍了这座城镇怎样组织民兵。'),('The report distinguishes the regular army from local militias.','报告区分了正规军与当地民兵组织。'),sources=[S('militia'),M('militia'),K('militia')]),
E('militant','/ˈmɪlɪtənt/','激进而好斗的；积极斗争的；激进分子或武装分子','不是静静赞成某个主张，而是准备站出来强硬争取，甚至与反对者对抗。具体有没有使用武器，要由语境说明。','来自拉丁 militare“当兵、作战”的现在分词 militans，经法语或拉丁语进入英语。-ant 原来带“正在做”的意味，不是现代英语 militate 后来简单加出的词。',ANT,'形容词可说 militant protesters，强调姿态强硬；新闻里的 a militant 有时指武装组织成员。早期宗教 Church militant 则把人世中的教会比作仍在奋斗的群体，是另一种历史比喻。','a militant group；a militant attitude；militant activists；armed militants。','military 说军事领域；militant 说斗争姿态或身份，未必属于正规军。peaceful 与 militant 是否相冲突要看这里是否强调暴力。',('The union adopted a more militant tone during the dispute.','工会在争议期间采取了更强硬的语气。'),('The article identifies the militants as members of an armed group.','文章说明这些武装分子属于一个武装团体。'),sources=[S('militant'),M('militant')]),
E('paramilitary','英 /ˌpærəˈmɪlɪtəri/；美 /ˌpærəˈmɪləteri/','准军事的；准军事组织或成员','它有类似军队的组织、训练或装备，却不等同于普通正规军。可以把它理解成在正规军旁边、按军队方式运作的一类力量。','para- 在这里表示“旁边、近似” + military；是现代英语构词，不是“反对军事”。',A(ARY,'英语 para- + military → paramilitary','类似军队、与军队并行的组织或活动'),'既可作形容词，也可指组织或成员。某些准军事力量与国家机构联系紧密，另一些可能独立存在；这个词本身不能替代对具体组织性质的说明。','a paramilitary force；paramilitary training；a paramilitary organization。','militia 强调民兵式组织，paramilitary 强调类似军队的组织和运作方式；两者可能重叠，却不是处处能互换。',('The study compares regular armies with paramilitary organizations.','这项研究比较了正规军与准军事组织。'),('The novel describes a paramilitary group operating outside the regular army.','小说描写了一个在正规军体系之外活动的准军事团体。'),sources=[S('paramilitary'),M('paramilitary'),K('paramilitary')]),
E('militarily','英 /ˈmɪlɪtərəli/；美 /ˌmɪləˈterəli/','在军事上；以军事方式','它像给一句判断加了一个视角框：“只从军事能力或军事手段这一面看。”','英语 military + -ly；词尾 y 变 i，形成 militarily。英美常见重音位置不同。',A(ARY,'英语 military + -ly → militarily','从军事角度；通过军事手段'),'militarily strong 说军事能力强，不等于经济或文化也强；intervene militarily 表示采取军事干预，而非外交或经济手段。','militarily strong；militarily significant；intervene militarily。','militarily 是领域或方式副词；militantly 是强硬、好斗地，强调态度。',('The island was militarily important because of its location.','这座岛屿因所处位置而在军事上很重要。'),('The leaders debated whether to respond militarily or diplomatically.','领导人讨论了应采取军事回应还是外交回应。'),sources=[M('militarily'),K('militarily')]),
E('militarist','英 /ˈmɪlɪtərɪst/；美 /ˈmɪlətərɪst/','军国主义者；崇尚军力的人','把强大军队和军事手段放到政治生活的中心，认为很多问题主要应靠军力解决的人。','英语 military 词基 + -ist 人。早期可指军人，后来尤其指 militarism 的支持者；不要因为现代意义相关，就把较早的词形说成必从较晚的 militarism 删尾而来。',A(ARY,'英语 military + -ist → militarist','早期军人；后来指崇尚军事力量或军国主义的人'),'它多用于分析政治立场，常带批评意味，也可作形容词修饰政策或观点。普通士兵并不因为职业是军人就自动成为 militarist。','a committed militarist；militarist policies；militarist thinking。','soldier 指职业或身份；militarist 指对军力和社会组织的思想倾向。',('The historian describes him as a militarist rather than simply a career officer.','历史学家认为他不仅是职业军官，还是崇尚军力的人。'),('The essay criticizes the influence of militarists on public policy.','这篇文章批评军国主义者对公共政策的影响。'),sources=[S('militarist'),M('militarist')]),
E('militaristic','/ˌmɪlɪtəˈrɪstɪk/','军国主义的；崇尚军事力量的','一个社会、政策或表达方式把军队、武力和军事纪律捧得特别高，甚至让它们压过其他解决问题的方式。','可分析为 militarist + -ic，或 military 词基 + -istic；是英语内部的形容词构成。',A(ARY,'英语 militarist + -ic / military 词基 + -istic → militaristic','具有军国主义或崇尚军力倾向的'),'它通常带评价意味。a military parade 只是军事阅兵；a militaristic culture 则在评价一种过度看重军力的文化倾向。','a militaristic society；militaristic rhetoric；a militaristic outlook。','military 是一般的“军事的”；militaristic 强调军事化思想或对军力的崇尚，语气更强。',('The novel portrays a rigid and militaristic society.','小说描绘了一个僵化而崇尚军事力量的社会。'),('Critics objected to the speech’s militaristic language.','批评者反对演讲中崇尚武力的措辞。'),sources=[M('militaristic'),K('militaristic')]),
E('militantly','/ˈmɪlɪtəntli/','强硬地；以积极对抗的姿态','不只是心里坚持，而是把立场公开摆出来，语气和行动都很不肯退让。','英语 militant + -ly；把“好斗、积极斗争的”变成表达态度或做事方式的副词。',A(ANT,'英语 militant + -ly → militantly','带强烈对抗性或积极斗争姿态地'),'militantly opposed 表示强硬反对；militantly independent 可以形容一个人非常坚持独立自主，未必有现实军事活动。词义强度随语境变化，但通常比 simply strongly 更有对抗感。','militantly opposed to；militantly independent；militantly defend a position。','militarily 说军事层面；militantly 说态度强硬。一个人可以 militantly independent，却与军队毫无关系。',('She remained militantly independent throughout her career.','她整个职业生涯都极力坚持独立自主。'),('The group was militantly opposed to the proposed merger.','这个团体强硬反对拟议中的合并。'),sources=[M('militantly'),K('militantly')]),
E('militarism','英 /ˈmɪlɪtərɪzəm/；美 /ˈmɪlətərɪzəm/','军国主义；崇尚军力的思想或体制','军队不再只是社会中的一个部门，而是军事力量和军事价值在公共生活中占据过分突出的地位。','英语借自法语 militarisme，由 militaire“军事的”加 -isme。现代可联系 military 与 -ism 理解，但实际借入链经过法语名词。',MIL+[['拉丁 militaris → 法语 militaire','军事的'],['法语 militarisme → 英语 militarism','军事精神、对军力的崇尚；发展为军国主义及军事势力主导的体制倾向']],'它通常是在谈一种思想、政治风气或社会安排，不是泛指所有国防建设。理解时问：这句话是在描述拥有军队，还是在批评军力被放到了支配性位置？','the rise of militarism；oppose militarism；militarism and nationalism。','military service 是服兵役；militarism 是关于军力在社会中应占多大位置的思想或体制倾向。',('The historian examines the rise of militarism before the war.','历史学家考察了战争前军国主义的兴起。'),('The exhibition explores the relationship between propaganda and militarism.','展览探讨了宣传与军国主义之间的关系。'),sources=[S('militarism'),M('militarism')]),
E('militarize','英 /ˈmɪlɪtəraɪz/；美 /ˈmɪlətəraɪz/','使军事化；使具有军事用途或组织方式','给一个原本较少军事色彩的地方或机构增加军队、军事装备，或者让它按军事方式运作。','英语 military 词基 + -ize“使成为”。militarise 是常见英式拼写变体。',IZE,'可以说 militarize a border，指增加边境军事部署；militarize an institution 则可能说制度、装备或组织方式的改变。它描述的是变化，不一定直接说明是否开战。','militarize a region；militarize the border；militarize an institution。','arm 重点是配备武器；militarize 还可能涉及部署、指挥结构和组织方式。',('The proposal would further militarize the border region.','这项提议会让边境地区进一步军事化。'),('The author asks why the government chose to militarize civilian institutions.','作者追问政府为何选择让民用机构军事化。'),sources=[S('militarize'),M('militarize')]),
E('militarized','英 /ˈmɪlɪtəraɪzd/；美 /ˈmɪlətəraɪzd/','军事化的；已经实施军事化的','从“正在改变”移到“改变后的状态”：一个地方已经布置了显著的军事力量，或某机构已经采用军事式装备与组织。','英语 militarize 的过去式、过去分词；去词尾 e 加 -ed，也常独立作形容词。',A(IZE,'英语 militarize → militarized','已被赋予军事用途、部署或运作方式的'),'a heavily militarized border 强调军事部署程度高；a militarized society 则范围更广，可能包括社会组织与日常规范。英式也写 militarised。','a militarized zone；a heavily militarized border；a militarized institution。','military 说明本来属于军事领域；militarized 强调某物被改造成或变得具有军事性质。',('The film is set in a heavily militarized border town.','影片的故事发生在一座军事部署密集的边境城镇。'),('The report describes a militarized approach to a civilian problem.','报告描述了用军事化方式处理一个民事问题的做法。'),sources=[M('militarized'),K('militarized')]),
E('militarization','英 /ˌmɪlɪtəraɪˈzeɪʃən/；美 /ˌmɪlətərəˈzeɪʃən/','军事化过程；军事化程度的增长','把“给某地增加军事部署”或“让某机构更像军队”看成一个正在发生的过程。','现代可拆 militarize + -ation；历史上英语名词很可能对应、翻译法语 militarisation，因此不只把它解释成英语动词后来加尾。militarisation 也是英式拼写。',MIL+[['拉丁 militaris → 法语 militaire','军事的'],['法语 militarisation；英语 militarize + -ation 的构词对应','英语名词很可能受已有法语名词影响'],['英语 militarization','使军事化的过程或结果']],'the militarization of a region 可以讨论驻军、设施与控制方式的变化；the militarization of language 也可以比喻讲话越来越采用战争和敌我对抗的框架。','the militarization of a border；increasing militarization；resist militarization。','militarism 是崇尚军力的思想或体制倾向；militarization 是变得军事化的过程，两者相关但不相同。',('The report documents the gradual militarization of the region.','报告记录了该地区逐步军事化的过程。'),('The essay discusses the militarization of everyday language.','文章讨论了日常语言越来越采用军事化表达的现象。'),sources=[S('militarization'),M('militarization'),K('militarization')]),
E('demilitarize','英 /ˌdiːˈmɪlɪtəraɪz/；美 /ˌdiːˈmɪlətəraɪz/','使非军事化；撤除军事设施或部署','把已有的军事力量、装备或用途撤掉，让某个地方或机构不再保持原来的军事状态。','英语 de- 撤除、逆转 + militarize；不是“再军事化”，后者用 re-。英式也写 demilitarise。',DE,'可用于地区，也可用于设备或制度。不同协议对“撤到什么程度”有不同规定，因此词义是去除军事性质，而不是自动保证当地从此没有一名持械人员。','demilitarize a region；demilitarize an island；a demilitarized zone。','disarm 主要是解除武装；demilitarize 常同时涉及驻军、设施和军事用途。',('The agreement required both sides to demilitarize the narrow strip of land.','协议要求双方使那条狭长地带非军事化。'),('The plan aims to demilitarize the island and restore civilian use.','计划旨在撤除该岛的军事用途，恢复民用。'),sources=[S('demilitarize'),M('demilitarize')]),
E('demilitarization','英 /ˌdiːmɪlɪtəraɪˈzeɪʃən/；美 /ˌdiːmɪlətərəˈzeɪʃən/','非军事化；解除军事部署的过程','把一片地方从“以军事部署为主”逐步改回非军事用途，关注的是这一整套撤除和转变。','英语 demilitarize 对应的 -ation 动作名词；亦写 demilitarisation。',A(DE,'英语 demilitarize + -ation → demilitarization','撤除军事组织、部署或用途的过程'),'它常出现在和平协议与历史分析中，也可讨论机构的转型。这个词说的是过程及安排，不直接等于双方所有政治分歧都已解决。','the demilitarization of a zone；a demilitarization agreement；monitor demilitarization。','demobilization 常指军人复员、部队解除动员；demilitarization 重点是地区或机构的军事性质被撤除。',('The treaty sets out a timetable for demilitarization.','条约列出了非军事化的时间表。'),('The museum explains how demilitarization changed the town’s economy.','博物馆说明了非军事化怎样改变了这座城镇的经济。'),sources=[M('demilitarization'),K('demilitarization'),S('demilitarize')]),
E('militancy','/ˈmɪlɪtənsi/','激进好斗的态度；积极斗争的倾向','把“愿意强硬争取、公开对抗”这一特点整体拿出来说，而不是指某一名具体的人。','英语 militant 对应的 -cy 抽象名词；-ant 与 -ancy 在这类形容词和名词之间形成对应。',A(ANT,'英语 militant → militancy','好斗、强硬争取的状态或倾向'),'growing militancy 可以描述某群体越来越愿意采取对抗性行动。具体是言辞强硬、罢工、直接行动还是武装活动，要看语境，不能把抽象名词一律等同于持枪。','growing militancy；union militancy；political militancy。','militant 可指人或形容态度；militancy 把这种态度或倾向作为抽象性质讨论。',('The study links growing militancy to years of failed negotiations.','研究把日益强硬的斗争倾向与多年谈判失败联系起来。'),('Her speech showed determination without encouraging militancy.','她的讲话表现出坚定，却没有鼓励对抗性行动。'),sources=[S('militancy'),M('militancy')]),
E('militate','/ˈmɪlɪteɪt/','产生有分量的影响；常指妨碍、不利于','把某个因素想成站在计划对面的一支力量：高成本、时间不足等都可能“和计划作对”，使它难以实现。','来自拉丁 militare“当兵、作战”，其分词词干 militat- 进入英语。词义从作战、相冲突，发展为某因素对结果起作用。',MIL+[['拉丁 militare → 分词词干 militat-','当兵、作战'],['英语 militate','早期当兵；后来与某事相抵触、对结果产生影响']],'最常见 militate against something，主语往往是事实、条件或证据。也可见 militate in favor of，表示构成有利因素，但 against 更值得先掌握。它通常不直接接宾语。','militate against success；factors that militate against a plan；militate in favor of。','mitigate 是减轻坏处；militate against 是构成阻碍。High costs militate against the plan；a subsidy may mitigate those costs。',('The short deadline militates against a careful review.','期限太短，不利于仔细审查。'),('Several practical difficulties militate against the proposal.','若干实际困难使这项提议难以推行。'),sources=[S('militate'),M('militate')]),
E('militiaman','/məˈlɪʃəmən/','民兵成员；男性民兵','把 militia 这支组织缩小到其中一个人：他是民兵组织的一员，而不只是泛泛地“态度激进”。','英语 militia 民兵组织 + man 人、男子；是英语复合词，两个部分并非都来自拉丁 milit-。复数 militiamen。',A(ITIA,'英语 militia + man → militiaman','一名民兵组织成员'),'历史文献中常见这个词。指性别不限的成员时，a militia member 更清楚；militiaman 的 man 仍可能让人理解为男性。','a local militiaman；a former militiaman；a group of militiamen。','militiaman 是组织成员身份；militant 可能是态度激进者，也可能在新闻中指武装分子，不自动等于民兵。',('The letter was written by a young militiaman.','这封信是一名年轻民兵写的。'),('Several militiamen appear in the photograph beside the town hall.','照片中几名民兵站在市政厅旁。'),sources=[S('militiaman'),M('militiaman')]),
]
ROOT=dict(id='C0738',meaning='士兵；服兵役、作战',core='milit- 的起点是士兵。它向两边发展：一边说军队、军事组织和军事化，另一边把“作战”的姿态带进意见与行动，表示强硬斗争，甚至让事实条件像一股力量那样阻挡某事。',image='一名士兵是起点：military 描写军队相关事物，militia 是民兵组织，militant 把作战姿态借给立场；militate against 则把困难想成站在计划对面的力量。',intro='来自拉丁 miles“士兵”，属格 militis，词干 milit-。miles 的更早来源存在不同推测，不把它与“千人队”或英语 mile 的关系写成定论。military、militia、militant 各自有独立的拉丁或法语借入路线。',forms='milit- 见 militant、militia、militate；militar- 见 military 和 militarize。军事相关是 military，崇尚军力的思想倾向是 militaristic；mild、mile、million 不能只看开头相似就并入。',branches=[['军队与成员','military, militia, militiaman, paramilitary, militarily'],['强硬斗争的姿态','militant, militantly, militancy'],['崇尚军力的思想','militarism, militarist, militaristic'],['军事化及其逆转','militarize, militarized, militarization, demilitarize, demilitarization'],['因素像力量一样影响结果','militate']],contrasts='military 说军事领域，militant 说强硬斗争姿态，militaristic 说崇尚军力的倾向。militarism 是思想或体制倾向，militarization 是军事化过程。militate against 妨碍，mitigate 减轻，拼写相近而意义不同。',practice='The report discusses military policy, growing militancy, and factors that militate against compromise. 报告讨论军事政策、日益强硬的斗争倾向，以及妨碍妥协的因素。这里三个 milit- 词分别说领域、姿态和影响。',words=[],exclude={})
